namespace UrlShortener.Tests.Core;

public class LinkValidatorDenylistTests
{
    private readonly LinkValidator _validator = new("sho.rt", ["evil.example", "Phish.Example."]);

    [Theory]
    [InlineData("https://evil.example/login")]
    [InlineData("https://cdn.evil.example/x")]
    [InlineData("http://EVIL.EXAMPLE")]
    [InlineData("https://phish.example")]
    [InlineData("https://a.b.phish.example/path")]
    public void Rejects_blocked_domains_and_their_subdomains(string url)
    {
        var result = _validator.ValidateUrl(url);

        Assert.False(result.IsValid);
        Assert.Equal("URL points to a blocked domain.", result.Error);
    }

    [Theory]
    [InlineData("https://notevil.example")]
    [InlineData("https://evil.example.com")]
    [InlineData("https://example.com")]
    public void Allows_look_alikes_and_unrelated_domains(string url)
    {
        Assert.True(_validator.ValidateUrl(url).IsValid);
    }

    [Fact]
    public void Without_a_denylist_nothing_extra_is_blocked()
    {
        Assert.True(new LinkValidator("sho.rt").ValidateUrl("https://evil.example").IsValid);
    }
}
