using System.Net.Http.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc;

namespace UrlShortener.Tests.Api;

public sealed class BlockedDomainsTests : IAsyncLifetime
{
    private readonly ShortenerApiFactory _factory = new();
    private HttpClient _client = null!;

    public async Task InitializeAsync()
    {
        await _factory.InitializeDatabaseAsync();
        _client = _factory
            .WithWebHostBuilder(builder => builder.UseSetting("Shortener:BlockedDomains:0", "malware.example"))
            .CreateClient();
    }

    public async Task DisposeAsync()
    {
        _client.Dispose();
        await _factory.DisposeAsync();
    }

    [Fact]
    public async Task Creating_a_link_to_a_blocked_domain_returns_400()
    {
        var response = await _client.PostAsJsonAsync("/api/links", new { url = "https://login.malware.example/reset" });

        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
        var problem = await response.Content.ReadFromJsonAsync<ProblemDetails>();
        Assert.Equal("URL points to a blocked domain.", problem?.Detail);
    }

    [Fact]
    public async Task Other_domains_are_still_accepted()
    {
        var response = await _client.PostAsJsonAsync("/api/links", new { url = "https://example.com" });

        Assert.Equal(HttpStatusCode.Created, response.StatusCode);
    }
}
